const backToTop=document.querySelector('#back-to-top');
if(backToTop){
  backToTop.addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));
  let lastScrollY=window.scrollY;
  const toggleBackToTop=()=>{
    const currentY=window.scrollY;
    const scrollingUp=currentY<lastScrollY;
    backToTop.classList.toggle('show',currentY>480&&scrollingUp);
    lastScrollY=currentY;
  };
  window.addEventListener('scroll',toggleBackToTop,{passive:true});
  toggleBackToTop();
}

function syncAuthButton(){
  const btn=document.querySelector('#login-btn');
  if(!btn)return;
  let user=null;
  try{user=JSON.parse(localStorage.getItem('travelenfield-user')||'null')}catch{}
  if(user){btn.textContent='My Profile';btn.onclick=()=>{window.location.href='/profile'};}
  else{btn.textContent='Login';btn.onclick=()=>setLoginPopup(true);}
}
syncAuthButton();
document.addEventListener('travelenfield:login',syncAuthButton);
async function restoreSession(){
  try{const response=await fetch('/api/auth/me',{credentials:'same-origin'});if(response.ok){const result=await response.json();if(result.user)localStorage.setItem('travelenfield-user',JSON.stringify(result.user));}else{localStorage.removeItem('travelenfield-user');}}catch{}
  syncAuthButton();
}
restoreSession();

