function wireHotelBooking(hotel) {
  const form = document.querySelector('#hotel-booking-form'); if (!form) return;
  const today = new Date(); const later = new Date(); later.setDate(later.getDate() + 2);
  const checkin = form.querySelector('#book-checkin'); if (checkin && !checkin.value) checkin.value = isoDate(today);
  const checkout = form.querySelector('#book-checkout'); if (checkout && !checkout.value) checkout.value = isoDate(later);
  document.querySelectorAll('[data-room]').forEach(button => button.addEventListener('click', () => {
    const room = form.querySelector('#book-room');
    if (room) room.value = button.dataset.room;
    const price = form.querySelector('#book-price');
    if (price) price.textContent = money(Number(button.dataset.price));
    document.querySelector('.hotel-booking-sticky')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }));
  form.addEventListener('submit', async event => {
    event.preventDefault();
    const submit = form.querySelector('button[type=submit]');
    const status = form.querySelector('.form-status');
    submit.disabled = true; status.textContent = 'Reserving your stay…';
    try {
      const body = { ...Object.fromEntries(new FormData(form)), type: 'hotel-detail', destination: hotel.name, travellers: Number(form.querySelector('#book-guests')?.value || 1) };
      const response = await fetch('/api/enquiries', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
      if (!response.ok) throw new Error();
      status.className = 'form-status success'; status.textContent = 'Stay request received. Our hotel expert will call you shortly.'; form.reset();
      const checkin2 = form.querySelector('#book-checkin'); if (checkin2) checkin2.value = isoDate(new Date());
      const checkout2 = form.querySelector('#book-checkout'); if (checkout2) checkout2.value = isoDate(new Date(Date.now() + 2 * 86400000));
    } catch {
      status.className = 'form-status error'; status.textContent = 'Could not save right now. Please try again.';
    } finally {
      submit.disabled = false;
    }
  });
}

function wireFaq(root = mount) {
  root.querySelectorAll('.faq-item').forEach((item, index) => {
    const question = item.querySelector('.faq-question');
    const answer = item.querySelector('.faq-answer');
    if (!question || !answer) return;
    const answerId = `faq-answer-${index + 1}`;
    answer.id = answerId;
    question.setAttribute('aria-controls', answerId);
    question.addEventListener('click', () => {
      const willOpen = !item.classList.contains('open');
      root.querySelectorAll('.faq-item.open').forEach(openItem => {
        if (openItem !== item) {
          openItem.classList.remove('open');
          openItem.querySelector('.faq-question')?.setAttribute('aria-expanded', 'false');
        }
      });
      item.classList.toggle('open', willOpen);
      question.setAttribute('aria-expanded', String(willOpen));
    });
  });
}

